Probe source, kept here because the crate is deleted before this bead closes. To rebuild it, put these two files in rust/beryl3d/crates/beryl_probe/ and run the cargo commands in the closing comment.

=== Cargo.toml
[package]
name = "beryl_probe"
version = "0.1.0"
description = "Throwaway: links every dependency Beryl 3D plans, to see that each target builds"
edition.workspace = true
license.workspace = true
publish = false

[features]
default = ["session", "wgpu", "winit", "taffy", "parley", "glam", "bytemuck", "pollster", "image", "ctt", "postcard", "swash", "tiny-skia", "rodio"]
session = ["dep:beryl_session", "dep:beryl_cards"]
wgpu = ["dep:wgpu", "pollster"]
winit = ["dep:winit"]
taffy = ["dep:taffy"]
parley = ["dep:parley"]
glam = ["dep:glam"]
bytemuck = ["dep:bytemuck"]
pollster = ["dep:pollster"]
image = ["dep:image"]
ctt = ["dep:ctt"]
postcard = ["dep:postcard"]
swash = ["dep:swash"]
tiny-skia = ["dep:tiny-skia"]
rodio = ["dep:rodio"]

[dependencies]
beryl_session = { path = "../../../crates/beryl_session", optional = true }
beryl_cards = { path = "../../../crates/beryl_cards", optional = true }
wgpu = { version = "30.0.2", optional = true }
taffy = { version = "0.15.1", optional = true }
parley = { version = "0.13.0", optional = true }
glam = { version = "0.34.3", optional = true }
bytemuck = { version = "1.25.2", features = ["derive"], optional = true }
pollster = { version = "1.0.1", optional = true }
image = { version = "0.25.10", default-features = false, features = ["jpeg", "png"], optional = true }
ctt = { version = "0.6.1", default-features = false, features = ["encoder-astcenc", "encoder-etcpak", "encoder-bc7f"], optional = true }
postcard = { version = "1.1.3", default-features = false, features = ["alloc"], optional = true }
swash = { version = "=0.2.10", optional = true }
tiny-skia = { version = "=0.12.0", optional = true }
rodio = { version = "=0.23.0", default-features = false, features = ["playback", "mp4"], optional = true }

# The phones get native Swift and Kotlin hosts (decision C7); winit is the desktop host only.
[target.'cfg(not(any(target_os = "ios", target_os = "android")))'.dependencies]
winit = { version = "0.30.13", optional = true }

=== src/main.rs
//! Throwaway: touches every dependency so the linker keeps real code from each.
//! Every input comes from the command line so nothing folds to a constant.
#![allow(unsafe_code, clippy::pedantic, unused)]

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let path = args.get(1).cloned().unwrap_or_default();
    let bytes = std::fs::read(&path).unwrap_or_default();
    let text = args.get(2).cloned().unwrap_or_else(|| "Pay {1}{U}".to_owned());
    let mut sink = 0usize;

    #[cfg(feature = "session")]
    {
        let sessions = beryl_session::Sessions::new(None, |_update| {});
        let deck = beryl_cards::decks::default_deck();
        let start = beryl_session::StartGame {
            seed: bytes.len() as u64,
            decks: [deck.clone(), deck],
            human: beryl_session::Seat::P0,
            opponent: "mcts-hidden".to_owned(),
            stops: beryl_session::protocol::StopsSetting::SMART,
        };
        sink += sessions.start_game(&start, Some("expert")).is_ok() as usize;
    }
    #[cfg(feature = "wgpu")]
    {
        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
        let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()));
        if let Ok(adapter) = adapter {
            let info = adapter.get_info();
            println!("adapter: {} ({:?})", info.name, info.backend);
            if let Ok((device, _queue)) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default())) {
                let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
                    label: None,
                    source: wgpu::ShaderSource::Wgsl(format!("@fragment fn main() -> @location(0) vec4<f32> {{ return vec4<f32>({}.0); }}", text.len()).into()),
                });
                sink += std::mem::size_of_val(&module);
            }
        } else {
            println!("adapter: none");
        }
    }
    #[cfg(all(feature = "winit", not(any(target_os = "ios", target_os = "android"))))]
    {
        if args.len() > 5 {
            let event_loop = winit::event_loop::EventLoop::new().unwrap();
            sink += std::mem::size_of_val(&event_loop);
        }
    }
    #[cfg(feature = "taffy")]
    {
        use taffy::prelude::*;
        let mut tree: TaffyTree<()> = TaffyTree::new();
        let leaf = tree.new_leaf(Style { size: Size { width: length(text.len() as f32), height: auto() }, ..Default::default() }).unwrap();
        let root = tree.new_with_children(Style { display: Display::Flex, ..Default::default() }, &[leaf]).unwrap();
        tree.compute_layout(root, Size::MAX_CONTENT).unwrap();
        sink += tree.layout(leaf).unwrap().size.width as usize;
    }
    #[cfg(feature = "parley")]
    {
        let mut font_cx = parley::FontContext::new();
        if !bytes.is_empty() {
            font_cx.collection.register_fonts(parley::fontique::Blob::new(std::sync::Arc::new(bytes.clone())), None);
        }
        let mut layout_cx: parley::LayoutContext<()> = parley::LayoutContext::new();
        let mut builder = layout_cx.ranged_builder(&mut font_cx, &text, 1.0, true);
        builder.push_default(parley::StyleProperty::FontSize(16.0));
        let mut layout: parley::Layout<()> = builder.build(&text);
        layout.break_all_lines(Some(100.0));
        sink += layout.width() as usize;
    }
    #[cfg(feature = "glam")]
    {
        let m = glam::Mat4::from_scale_rotation_translation(glam::Vec3::splat(text.len() as f32), glam::Quat::IDENTITY, glam::Vec3::ONE);
        sink += m.inverse().x_axis.x as usize;
    }
    #[cfg(feature = "bytemuck")]
    {
        #[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
        #[repr(C)]
        struct Record { a: [f32; 4] }
        let records = vec![Record { a: [text.len() as f32; 4] }];
        sink += bytemuck::cast_slice::<Record, u8>(&records).len();
    }
    #[cfg(feature = "image")]
    {
        if let Ok(decoded) = image::load_from_memory(&bytes) {
            let small = decoded.resize_exact(256, 360, image::imageops::FilterType::Triangle);
            let mut out = std::io::Cursor::new(Vec::new());
            small.write_to(&mut out, image::ImageFormat::Png).ok();
            sink += out.into_inner().len();
        }
    }
    #[cfg(feature = "ctt")]
    {
        let pixels = vec![text.len() as u8; 256 * 360 * 4];
        for (name, f) in [("astc_4x4", ctt::Format::ASTC_4x4_SRGB_BLOCK), ("etc2_rgba", ctt::Format::ETC2_R8G8B8A8_SRGB_BLOCK), ("bc7", ctt::Format::BC7_SRGB_BLOCK)] {
            let format = ctt::TargetFormat::Compressed { format: f, encoder: ctt::encoders::Encoder::Auto };
            let image = ctt::ImageRef {
                surfaces: vec![vec![ctt::SurfaceRef { data: &pixels, width: 256, height: 360, depth: 1, stride: 256 * 4, slice_stride: 0 }]],
                kind: ctt::TextureKind::Texture2D,
                desc: ctt::FormatDesc { format: ctt::Format::R8G8B8A8_SRGB, color_space: ctt::ColorSpace::Srgb, alpha: ctt::AlphaMode::Straight },
            };
            let result = ctt::convert(image, ctt::ConvertSettings { format: Some(format), container: ctt::Container::ktx2(), ..Default::default() });
            println!("ctt {name}: {}", if result.is_ok() { "ok" } else { "error" });
            sink += result.is_ok() as usize;
        }
    }
    #[cfg(feature = "postcard")]
    {
        let encoded = postcard::to_allocvec(&(text.len() as u32, text.as_str())).unwrap();
        let decoded: (u32, &str) = postcard::from_bytes(&encoded).unwrap();
        sink += decoded.0 as usize;
    }
    #[cfg(feature = "swash")]
    {
        if let Some(font) = swash::FontRef::from_index(&bytes, 0) {
            let mut context = swash::scale::ScaleContext::new();
            let mut scaler = context.builder(font).size(24.0).build();
            let glyph = font.charmap().map('U');
            let image = swash::scale::Render::new(&[swash::scale::Source::Outline]).render(&mut scaler, glyph);
            sink += image.map_or(0, |i| i.data.len());
            let mut shaper_cx = swash::shape::ShapeContext::new();
            let mut shaper = shaper_cx.builder(font).size(24.0).build();
            shaper.add_str(&text);
            shaper.shape_with(|cluster| sink += cluster.glyphs.len());
        }
    }
    #[cfg(feature = "tiny-skia")]
    {
        let mut pixmap = tiny_skia::Pixmap::new(256, 360).unwrap();
        let rect = tiny_skia::Rect::from_xywh(8.0, 8.0, text.len() as f32 * 10.0, 100.0).unwrap();
        let path = tiny_skia::PathBuilder::from_rect(rect);
        let mut paint = tiny_skia::Paint::default();
        paint.set_color_rgba8(200, 100, 50, 255);
        pixmap.fill_path(&path, &paint, tiny_skia::FillRule::Winding, tiny_skia::Transform::identity(), None);
        sink += pixmap.data()[8 * 256 * 4 + 40] as usize;
    }
    #[cfg(feature = "rodio")]
    {
        if let Ok(decoder) = rodio::Decoder::new_mp4(std::io::Cursor::new(bytes.clone())) {
            use rodio::Source;
            sink += decoder.sample_rate().get() as usize;
        }
        if args.len() > 4 {
            if let Ok(device) = rodio::DeviceSinkBuilder::open_default_sink() {
                sink += std::mem::size_of_val(&device);
            }
        }
    }
    println!("sink {sink}");
}

