Files: beryl_scene/src/agent/checks.rs, agent/fault.rs, text/glyphs.rs, widgets/icons.rs, client/screen.rs (`missing_glyphs`), beryl_3d/src/frame_log.rs, beryl_host/src/headless.rs.","acceptance_criteria":"A new interface check faults when a laid-out line's glyph or an icon has no atlas cell after delivery; a test shows it fails on a frame with a missing glyph; it runs in just b3d test at scale 1 and 2.","status":"in_progress","priority":1,"issue_type":"task","assignee":"vizier:jarvis:claude:32f74257-d3b1-4102-8f70-a1d50feaf650","owner":"ci@example.com","created_at":"2026-11-17T03:24:45Z","created_by":"Derek Thurn","updated_at":"2026-11-17T04:17:12Z","started_at":"2026-11-17T04:17:12Z","lease_expires_at":"2026-11-17T04:22:12Z","heartbeat_at":"2026-11-17T04:17:12Z","metadata":{"enact_run":"by-q44s","enact_vizier":"32f74257-d3b1-4102-8f70-a1d50feaf650","enact_spawn_app":"claude","enact_spawn_host":"jarvis","enact_reservation":"1c489111d4114701b7e1a2a4f7a0ec96","enact_pool_session":"local_7dc6b0ab-bf81-429a-96ca-4bbdeb77a944","enact_spawn_project":"/Users/dthurn/beryl","enact_spawn_provider":"claude"},"labels":["role:executor","tier:opus"]}

